import {UntypedFormControl, ValidatorFn} from '@angular/forms';
import {IValidator} from '../../interface/validation/i-validator';
import { Bundesland } from '../../enum/bundesland.enum';

export class ValidatorBetriebsnummer implements IValidator {

  public hasError = false;
  public _error = null;
  private value: any;

  public static REGEX_BY = /^(276)?09[0-9]{10}$/
  public static REGEX_NI = /^(276)?03[0-9]{10}$/
  public static REGEX_SH = /^(276)?01[0-9]{10}$/

  private blRegex: RegExp = ValidatorBetriebsnummer.REGEX_BY;
  private blNummer: string = '09';

  constructor(
    idBundesland: Bundesland = Bundesland.Bayern,
    error?: string
  ) {
    switch(idBundesland) {
      case Bundesland.Bayern:
        this.blRegex = ValidatorBetriebsnummer.REGEX_BY;
        this.blNummer = '09';
        break;
      case Bundesland.Niedersachsen:
        this.blRegex = ValidatorBetriebsnummer.REGEX_NI;
        this.blNummer = '03';
        break;
      case Bundesland.Schleswig_Holstein:
        this.blRegex = ValidatorBetriebsnummer.REGEX_SH;
        this.blNummer = '01';
        break;
      default:
        this.blRegex = ValidatorBetriebsnummer.REGEX_BY;
        this.blNummer = '09';
        break;
    }

    if (error) {
      this._error = error;
    }
  }

  public get error(): string {
    return this._error ?? `Die Betriebsnummer muss mit ${this.blNummer} beginnen, gefolgt von 10 Ziffern. Optional kann die Landesnummer 276 (Deutschland) vorangestellt werden.`;
  }

  public validator(): ValidatorFn {
    return (input: UntypedFormControl) => {
      this.value = input.value;
      return this.validate();
    };
  }

  public validate(): any {

    this.hasError = false;
    if (!this.value) {
      return null;
    }
    if (this.blRegex.test(this.value.toString())) {
      return null;
    } else {
      this.hasError = true;
      return {invalidBetriebsnr: true};
    }
  }
}
