import {UntypedFormControl, ValidatorFn} from '@angular/forms';
import * as _ from 'underscore';
import { Util } from '../util/util';
import { IValidator } from '../../interface/validation/i-validator';

export class ValidatorIntegerRange implements IValidator {

  public error = 'Bitte geben Sie eine ganze Zahl ein';
  public hasError: boolean;
  private value$: string;


  constructor(
    private minValue$: number = undefined,
    private maxValue$: number = undefined,
    private showSmallError: boolean = false
  ) {

  }

  public get smallError(): string {
    return `${Util.isDefined(this.minValue$) ? 'min: ' + this.minValue$ + (Util.isDefined(this.maxValue$) ? ', ' : '') : ''}${Util.isDefined(this.maxValue$) ? 'max: ' + this.maxValue$ : ''}`;
  }

  public validate(): any {
    this.hasError = false;
    if (!Util.isDefined(this.value$)) {
      return null;
    }
    let checkVal;
    if (_.isString(this.value$)) {
      checkVal = Number.parseFloat(this.value$);
    } else {
      checkVal = Number(this.value$);
    }
    
    if (checkVal < this.minValue$ || checkVal > this.maxValue$) {
      if (this.showSmallError) {
        this.error = this.smallError;
      } else {
        this.error = `Bitte wählen Sie eine Zahl zwischen ${this.minValue$} und ${this.maxValue$}`;
      }
      this.hasError = true;
      return {invalidIntegerRange: true};
    }
    return null;
  }

  public validator(): ValidatorFn {
    return (input: UntypedFormControl) => {
      this.value$ = input.value;
      return this.validate();
    };
  }

}