import * as _ from 'underscore';
import {IValidator} from '../../interface/validation/i-validator';
import {AbstractControl, ValidatorFn} from '@angular/forms';
import {Util} from '../util/util';

export class ValidatorLength implements IValidator {

  public static readonly ERROR_MAXLENGTH = 'Dieses Feld darf maximal __MAX_LENGTH__ Zeichen enthalten.';
  public static readonly ERROR_MINLENGTH = 'Dieses Feld muss minimal __MIN_LENGTH__ Zeichen enthalten.';

  public error: string;
  public hasError: boolean;
  private value: any;

  constructor(
    public maxLength?: number,
    public minLength?: number
  ) {
  }

  public validator(): ValidatorFn {
    return (input: AbstractControl): object | null => {
      this.value = input.value;
      return this.validate();
    };
  }

  public validate(): any {
    this.hasError = false;
    if (this.value === null || this.value === undefined || (_.isString(this.value) && _.isEmpty(this.value))) {
      return null;
    }
    if (Util.isDefined(this.maxLength)) {
      if (this.value.toString().length > this.maxLength) {
        this.hasError = true;
        this.error = ValidatorLength.ERROR_MAXLENGTH.replace('__MAX_LENGTH__', this.maxLength.toString());
        return {invalidMaxLength: true};
      }
    }
    if (Util.isDefined(this.minLength)) {
      if (this.value.toString().length < this.minLength) {
        this.hasError = true;
        this.error = ValidatorLength.ERROR_MINLENGTH.replace('__MIN_LENGTH__', this.minLength.toString());
        return {invalidMinLength: true};
      }
    }
    return null;
  }

}
