import {IValidator} from '../../interface/validation/i-validator';
import {FormControl} from '@angular/forms';
import * as _ from 'underscore';
import {ValidatorRequired} from '../../impl/validation/validator-required';
import {IAccessableFormControl, IAccessableFormOptions} from '../../interface/validation/i-accessable-form-control';
import { Observable, Observer } from 'rxjs';


export class AccessableFormControl<TType = any>
  implements IAccessableFormControl<AccessableFormControl<TType>, TType> {

  public control: FormControl;
  public showAs: (value: any) => any;
  public convertTo: (value: any) => any;
  private required$: boolean;
  private validators$: IValidator[];
  private blocked$: boolean;
  private previousValue$: any = null;
  private rawValue$: any;

  public initialize(
    formState?: any,
    validators?: IValidator[]
  ) {
    this.control = new FormControl(formState, null);
    this.validateWith(validators);
    this.setValue(formState, true);
  }

  public validateWith(validators: IValidator[] = [], opts?: IAccessableFormOptions): AccessableFormControl {
    this.validators$ = validators;
    this.control.setValidators(_.map(validators, (v: IValidator) => {
      return v.validator();
    }));
    this.required$ = false;
    _.each(this.validators$, (v: IValidator) => {
      if (v instanceof ValidatorRequired) {
        this.required$ = true;
      }
    });
    this.control.updateValueAndValidity(opts);
    return this;
  }

  public setValue(value: any, skipSetPreviousValue: boolean = false, opts?: IAccessableFormOptions): AccessableFormControl {
    if (!skipSetPreviousValue) {
      this.previousValue = this.value;
    }
    this.rawValue$ = value;
    if (this.showAs) {
      this.control.setValue(this.showAs(value), opts);
    } else {
      this.control.setValue(value, opts);
    }
    return this;
  }

  public reset(value: TType, skipSetPreviousValue: boolean = false, opts?: IAccessableFormOptions): AccessableFormControl {
    if (!skipSetPreviousValue) {
      this.previousValue = this.value;
    }
    this.rawValue$ = value;
    if (this.showAs) {
      this.control.reset(this.showAs(value), opts);
    } else {
      this.control.reset(value, opts);
    }
    return this;
  }

  public markAsUsed(opts?: IAccessableFormOptions): AccessableFormControl {
    this.control.markAsDirty(opts);
    this.control.markAsTouched(opts);
    this.control.updateValueAndValidity(opts);
    return this;
  }

  public markAsUnused(opts?: IAccessableFormOptions): AccessableFormControl {
    _.each(this.validators$, (validator: IValidator) => validator.hasError = false );
    this.control.updateValueAndValidity(opts);
    this.control.markAsPristine(opts);
    this.control.markAsUntouched(opts);
    return this;
  }

  public markAsDirty(opts?: IAccessableFormOptions): AccessableFormControl {
    this.control.markAsDirty(opts);
    return this;
  }

  public markAsTouched(opts?: IAccessableFormOptions): AccessableFormControl {
    this.control.markAsTouched(opts);
    return this;
  }

  public disable(opts?: IAccessableFormOptions): AccessableFormControl {
    this.control.disable(opts);
    return this;
  }

  public enable(opts?: IAccessableFormOptions): AccessableFormControl {
    this.control.enable(opts);
    return this;
  }

  public blockControls(): void {
    this.blocked$ = true;
  }

  public unblockControls(): void {
    this.blocked$ = false;
  }

  get disabled(): boolean {
    return this.control.disabled;
  }

  get valid(): boolean {
    if (this.control.disabled) {
      return true;
    }
    return !this.error;
  }

  get validators(): IValidator[] {
    return this.validators$;
  }

  get error(): IValidator {
    return _.find(this.validators$, (v: IValidator) => v.hasError );
  }

  get value(): any {
    if (this.convertTo) {
      return this.convertTo(this.control.value);
    } else {
      return this.control.value;
    }
  }

  set value(value: any) {
    this.setValue(value);
  }

  get valueChanges(): Observable<any> {
    return Observable.create( (observer: Observer<any>) => {
      const sub = this.control.valueChanges
        .subscribe(
          () => {
            if (!this.blocked) {
              observer.next(this.value);
            }
          },
          null,
          () => {
            sub.unsubscribe();
          }
        );
    });
  }

  get rawValue(): any {
    return this.rawValue$;
  }

  get rawValueAsType(): TType {
    return this.convertTo(this.rawValue);
  }

  get previousValue(): any {
    return this.previousValue$;
  }

  set previousValue(value: any) {
    this.previousValue$ = value;
  }

  get required(): boolean {
    return this.required$;
  }

  get touched(): boolean {
    return this.control.touched;
  }

  get dirty(): boolean {
    return this.control.dirty;
  }

  get blocked(): boolean {
    return this.blocked$;
  }

}
