import {IValidator} from '../../interface/validation/i-validator';
import {AccessableFormControl} from '../../abstract/validation/accessable-form-control';
import {TypeConverter} from '../util/type-converter';
import {Util} from '../util/util';
import { REGEX } from '../../enum/regex';
import * as _ from 'underscore';
import { ValidatorFloat } from './validator-float';
import { Moment } from 'moment';

export abstract class AccessableControlFactory {

  public static simpleControl(
    formState: any = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = new AccessableFormControl();
    control.initialize(formState, validators);
    return control;
  }

  public static numberControl(
    formState: any = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(formState, validators);
    control.showAs = TypeConverter.asGermanFloat;
    control.convertTo = TypeConverter.toNumber;
    control.setValue(formState);
    return control;
  }

  public static numberBooleanControl(
    formState: any = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(formState, validators);
    control.showAs = TypeConverter.numberToBoolean;
    control.convertTo = TypeConverter.booleanToNumber;
    control.setValue(formState);
    return control;
  }

  public static numberDigitsControl(
    formState: any = null,
    validators: IValidator[],
    digits: number = 3
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(null, validators);
    control.showAs = (n: number): string | undefined | null => {
      return TypeConverter.asGermanFloat(n, digits);
    };
    control.convertTo = TypeConverter.toNumber;
    control.setValue(formState);
    return control;
  }

  /**
     * Erzeuge eine AccessableFormControl für eine Zahl mit {digits} oder {minDigits}/{maxDigits} Nachkommastellen und einem Tausenderpunkt.
     */
  public static numberDigitsExtendedControl(
    formState: any = null,
    validators: IValidator[],
    digits: number = 3,
    minDigits?: number,
    maxDigits: number = 100,
    // trennpunkt: boolean = false, // Klappt noch nicht
  ): AccessableFormControl {
    let validatorFloat: ValidatorFloat = _.find(validators, (v: IValidator) => v instanceof ValidatorFloat);
    if (!Util.isDefined(validatorFloat)) {
      validatorFloat = new ValidatorFloat(null, digits ?? maxDigits);
      validators.push(validatorFloat);
    }

    const control = AccessableControlFactory.simpleControl(null, validators);

    if (true) { // !trennpunkt
      control.showAs = (n: number): string | undefined | null => {
        if (Util.isDefined(digits)) {
          return TypeConverter.asGermanFloat(n, digits);
        } else if (Util.isDefined(minDigits) && Util.isDefined(maxDigits)) {
          if (!Util.isDefined(n)) {
            return undefined;
          }
          if (!_.isNumber(n) || _.isNaN(Number(n))) {
            return n.toString();
          }
          return Number(Number(n).toFixed(maxDigits)).toLocaleString(
            'de-DE',
            {
                minimumFractionDigits: minDigits,
                maximumFractionDigits: maxDigits
            }).replace('.', '');
        } else {
          return TypeConverter.asGermanFloat(n);
        }
      };
      control.convertTo = TypeConverter.toNumber;
    } else {
      control.showAs = (n: number): string | undefined | null => {
        if (!Util.isDefined(n)) {
          return undefined;
        }
        if (!_.isNumber(n) || _.isNaN(Number(n))) {
          return n.toString();
        }
        if (Util.isDefined(digits)) {
          minDigits = digits;
          maxDigits = digits;
        } else if (!Util.isDefined(minDigits) && !Util.isDefined(maxDigits)) {
          minDigits = 3;
          maxDigits = 3;
        }
        return Number(Number(n).toFixed(maxDigits)).toLocaleString(
          'de-DE',
          {
              minimumFractionDigits: minDigits,
              maximumFractionDigits: maxDigits
          });
      };
      control.convertTo = (value: string | number): number | string  => {
        // Falls null oder undefined übergeben wurde, brechen wir ab
        if (!value) {
          return value;
        }
        // Falls der Wert bereits eine Zahl ist, sind wir fertig
        if (_.isNumber(value)) {
          return value;
        }
        // Falls der Wert ein String ist, testen wir, ob er aussieht wie eine Zahl und versuchen ihn anschließend zu konvertieren
        if (_.isString(value) && REGEX.ALL_NUMBERS.test(value as string)) {
          return Number.parseFloat((value as string).replace(/\./g, '').replace(',', '.'));
        }
        // Wir haben keine Regel für die Konvertierung gefunden
        return value;
      }
    }
    
    control.setValue(formState);
    return control;
  }

  public static dateControl(
    formState: any = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(formState, validators);
    return control;
  }

  public static momentDateControl(
    formState: string | moment.Moment | null = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(null, validators);
    control.showAs = TypeConverter.asGermanDate;
    control.convertTo = TypeConverter.toMoment;
    control.setValue(formState);
    return control;
  }

  public static momentTimeControl(
    formState: string | moment.Moment | null = null,
    validators: IValidator[],
    withSeconds: boolean = false, 
    withMilliseconds: boolean = false
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(null, validators);
    control.showAs = (v: string|Moment) => {
      return TypeConverter.asGermanTime(v, withSeconds, withMilliseconds);
    }
    control.convertTo = TypeConverter.toMoment; 
    control.setValue(formState);
    return control;
  }

  /** Schneides alle Whitespaces am Ende und Anfang weg */
  public static trimControl(
    formState: any = null,
    validators: IValidator[]
  ): AccessableFormControl {
    const control = AccessableControlFactory.simpleControl(formState, validators);
    control.showAs = (str: string): string | undefined | null => {
      if (Util.isDefined(str)) {
        return str.trim();
      }
      return str;
    };
    control.convertTo = (str: string): string | undefined | null => {
      if (Util.isDefined(str)) {
        return str.trim();
      }
      return str;
    };
    return control;
  }
}
